/**
 * A short text hint shown on hover or focus (`design/components/tooltip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tooltip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import * as zag from '@zag-js/tooltip'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  derived,
  elementRef,
  mergeParts,
  normalizeProps,
  setup,
  syncTriggerAnchor,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/tooltip.module.css'

export type TooltipAlign = NonNullable<TooltipProps['align']>

export type TooltipSide = NonNullable<TooltipProps['side']>

/** A short text hint shown on hover or focus: the inputs it takes, by the React member's prop names. */
export interface TooltipProps {
  align?: 'start' | 'center' | 'end'
  content: string
  /**
   * Opens on mount, for galleries and tests.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

/** A short text hint shown on hover or focus. */
@Component({
  selector: 'pm-tooltip',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, SlotOutlet, SlotTemplate, Spread],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- trigger -->
<span
[pmSpread]="e1()"
[pmRef]="anchor"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></span>
<ng-template pmPortal>@if (e2()) {<div
[pmSpread]="e3()"
><!-- bubble -->
<div
[pmSpread]="e4()"
[pmRef]="bubble"
>{{ e5() }}</div></div>}</ng-template>`,
})
export class Tooltip {
  readonly align = input<Exclude<TooltipProps['align'], undefined>, TooltipProps['align']>(
    'center',
    { transform: (value: TooltipProps['align']) => (value === undefined ? 'center' : value) },
  )
  readonly content = input.required<TooltipProps['content']>()
  /**
   * Opens on mount, for galleries and tests.
   */
  readonly defaultOpen = input<TooltipProps['defaultOpen']>(undefined)
  readonly side = input<Exclude<TooltipProps['side'], undefined>, TooltipProps['side']>('top', {
    transform: (value: TooltipProps['side']) => (value === undefined ? 'top' : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: {
      align: () => this.align(),
      content: () => this.content(),
      defaultOpen: () => this.defaultOpen(),
      side: () => this.side(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly anchor = elementRef<HTMLElement>()
  protected readonly bubble = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          defaultOpen: this.$p.defaultOpen,
          openDelay: TOOLTIP_DELAY_MS,
          closeDelay: TOOLTIP_SKIP_DELAY_MS,
          positioning: {
            placement:
              this.$p.align === 'center' ? this.$p.side : `${this.$p.side}-${this.$p.align}`,
            gutter: 0,
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly present = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.bubble.value,
      'tooltip.bubble',
      () => ({ side: this.$p.side, align: this.$p.align }),
    ),
  )

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
  }

  protected e1() {
    return mergeParts(anchorProps(this.api.value.getTriggerProps()), { class: styles.anchor })
  }

  protected e2() {
    return this.present.value()
  }

  protected e3() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps())
  }

  protected e4() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.bubble,
      style: { '--radix-tooltip-content-available-width': 'var(--available-width)' },
      hidden: undefined,
      'data-state': this.api.value.open ? 'delayed-open' : 'closed',
      'data-member': 'tooltip',
    })
  }

  protected e5() {
    if (!this.present.value()) return undefined as never
    return this.$p.content
  }

  private effect1(): void {
    syncTriggerAnchor(
      this.anchor.value,
      this.api.value.getTriggerProps(),
      this.api.value.open,
      false,
    )
  }
}
